package com.dawnyew.storage

import androidx.room.*

@Entity(tableName="accounts", primaryKeys=["id"], foreignKeys=[ForeignKey(entity=LedgerRow::class,parentColumns=["id"],childColumns=["ledgerId"],deferred=true)], indices=[Index(value=["ledgerId"]),Index(value=["ledgerId","normalizedName"],unique=true)])
data class AccountRow(val id:String, val ledgerId:String, val name:String, val type:String, val openingBalanceMinor:Long, val openingAt:String, val archived:Boolean, val hidden:Boolean, val includedInAssets:Boolean, val note:String, val sortOrder:Int, val revision:Long, val normalizedName:String, val position:Long, val payload:String)

@Entity(tableName="entry_details", primaryKeys=["entryId"], foreignKeys=[ForeignKey(entity=EntryRow::class,parentColumns=["id"],childColumns=["entryId"],onDelete=ForeignKey.CASCADE,deferred=true),ForeignKey(entity=AccountRow::class,parentColumns=["id"],childColumns=["accountId"],deferred=true),ForeignKey(entity=DimensionRow::class,parentColumns=["id"],childColumns=["projectId"],deferred=true),ForeignKey(entity=DimensionRow::class,parentColumns=["id"],childColumns=["merchantId"],deferred=true)], indices=[Index(value=["accountId"]),Index(value=["projectId"]),Index(value=["merchantId"])])
data class EntryDetailsRow(val entryId:String, val accountId:String?, val recorded:Boolean, val excludedFromBudget:Boolean, val reconciled:Boolean, val projectId:String?, val merchantId:String?, val position:Long, val payload:String)

@Entity(tableName="entry_tags", primaryKeys=["entryId","tagId"], foreignKeys=[ForeignKey(entity=EntryRow::class,parentColumns=["id"],childColumns=["entryId"],onDelete=ForeignKey.CASCADE,deferred=true),ForeignKey(entity=DimensionRow::class,parentColumns=["id"],childColumns=["tagId"],deferred=true)], indices=[Index(value=["entryId"]),Index(value=["tagId"])])
data class EntryTagRow(val entryId:String, val tagId:String, val position:Long, val payload:String)

@Entity(tableName="transfers", primaryKeys=["id"], foreignKeys=[ForeignKey(entity=LedgerRow::class,parentColumns=["id"],childColumns=["ledgerId"],deferred=true),ForeignKey(entity=AccountRow::class,parentColumns=["id"],childColumns=["fromAccountId"],deferred=true),ForeignKey(entity=AccountRow::class,parentColumns=["id"],childColumns=["toAccountId"],deferred=true)], indices=[Index(value=["ledgerId"]),Index(value=["fromAccountId"]),Index(value=["toAccountId"]),Index(value=["ledgerId","deleted","occurrence"])])
data class TransferRow(val id:String, val ledgerId:String, val fromAccountId:String?, val toAccountId:String?, val amountMinor:Long, val occurrence:String, val note:String, val recorded:Boolean, val reconciled:Boolean, val deleted:Boolean, val revision:Long, val createdAt:String, val updatedAt:String, val businessKind:String, val businessId:String?, val noteSearch:String, val position:Long, val payload:String)

@Entity(tableName="dimensions", primaryKeys=["id"], foreignKeys=[ForeignKey(entity=LedgerRow::class,parentColumns=["id"],childColumns=["ledgerId"],deferred=true)], indices=[Index(value=["ledgerId"]),Index(value=["ledgerId","kind","normalizedName"],unique=true)])
data class DimensionRow(val id:String, val ledgerId:String, val kind:String, val name:String, val archived:Boolean, val sortOrder:Int, val revision:Long, val normalizedName:String, val position:Long, val payload:String)

@Entity(tableName="contacts", primaryKeys=["id"], foreignKeys=[ForeignKey(entity=LedgerRow::class,parentColumns=["id"],childColumns=["ledgerId"],deferred=true)], indices=[Index(value=["ledgerId"]),Index(value=["ledgerId","normalizedName"],unique=true)])
data class ContactRow(val id:String, val ledgerId:String, val name:String, val note:String, val archived:Boolean, val revision:Long, val normalizedName:String, val position:Long, val payload:String)

@Entity(tableName="obligations", primaryKeys=["id"], foreignKeys=[ForeignKey(entity=LedgerRow::class,parentColumns=["id"],childColumns=["ledgerId"],deferred=true),ForeignKey(entity=AccountRow::class,parentColumns=["id"],childColumns=["virtualAccountId"],deferred=true),ForeignKey(entity=ContactRow::class,parentColumns=["id"],childColumns=["contactId"],deferred=true)], indices=[Index(value=["ledgerId"]),Index(value=["virtualAccountId"],unique=true),Index(value=["contactId"])])
data class ObligationRow(val id:String, val ledgerId:String, val kind:String, val title:String, val virtualAccountId:String, val openingAt:String, val contactId:String?, val dueDate:String?, val note:String, val archived:Boolean, val revision:Long, val position:Long, val payload:String)

@Entity(tableName="recurring_plans", primaryKeys=["id"], foreignKeys=[ForeignKey(entity=LedgerRow::class,parentColumns=["id"],childColumns=["ledgerId"],deferred=true),ForeignKey(entity=CategoryRow::class,parentColumns=["id"],childColumns=["categoryId"],deferred=true),ForeignKey(entity=AccountRow::class,parentColumns=["id"],childColumns=["accountId"],deferred=true),ForeignKey(entity=AccountRow::class,parentColumns=["id"],childColumns=["fromAccountId"],deferred=true),ForeignKey(entity=AccountRow::class,parentColumns=["id"],childColumns=["toAccountId"],deferred=true),ForeignKey(entity=DimensionRow::class,parentColumns=["id"],childColumns=["projectId"],deferred=true),ForeignKey(entity=DimensionRow::class,parentColumns=["id"],childColumns=["merchantId"],deferred=true)], indices=[Index(value=["ledgerId"]),Index(value=["categoryId"]),Index(value=["accountId"]),Index(value=["fromAccountId"]),Index(value=["toAccountId"]),Index(value=["projectId"]),Index(value=["merchantId"]),Index(value=["paused","archived"])])
data class RecurringPlanRow(val id:String, val ledgerId:String, val name:String, val kind:String, val amountMinor:Long, val anchor:String, val frequency:String, val totalOccurrences:Int?, val nextIndex:Int, val paused:Boolean, val archived:Boolean, val categoryId:String?, val accountId:String?, val fromAccountId:String?, val toAccountId:String?, val note:String, val recorded:Boolean, val excludedFromBudget:Boolean, val reconciled:Boolean, val projectId:String?, val merchantId:String?, val revision:Long, val position:Long, val payload:String)

@Entity(tableName="recurring_occurrences", primaryKeys=["id"], foreignKeys=[ForeignKey(entity=RecurringPlanRow::class,parentColumns=["id"],childColumns=["planId"],deferred=true),ForeignKey(entity=EntryRow::class,parentColumns=["id"],childColumns=["entryId"],deferred=true),ForeignKey(entity=TransferRow::class,parentColumns=["id"],childColumns=["transferId"],deferred=true)], indices=[Index(value=["planId"]),Index(value=["entryId"],unique=true),Index(value=["transferId"],unique=true),Index(value=["planId","index"],unique=true)])
data class RecurringOccurrenceRow(val id:String, val planId:String, val index:Int, val scheduledAt:String, val status:String, val entryId:String?, val transferId:String?, val position:Long, val payload:String)

@Entity(tableName="savings_plans", primaryKeys=["id"], foreignKeys=[ForeignKey(entity=LedgerRow::class,parentColumns=["id"],childColumns=["ledgerId"],deferred=true)], indices=[Index(value=["ledgerId"])])
data class SavingsPlanRow(val id:String, val ledgerId:String, val name:String, val scenario:String, val targetMinor:Long?, val note:String, val archived:Boolean, val revision:Long, val position:Long, val payload:String)

@Entity(tableName="savings_movements", primaryKeys=["id"], foreignKeys=[ForeignKey(entity=SavingsPlanRow::class,parentColumns=["id"],childColumns=["planId"],deferred=true),ForeignKey(entity=TransferRow::class,parentColumns=["id"],childColumns=["transferId"],deferred=true)], indices=[Index(value=["planId"]),Index(value=["transferId"],unique=true)])
data class SavingsMovementRow(val id:String, val planId:String, val kind:String, val amountMinor:Long, val occurrence:String, val note:String, val transferId:String?, val deleted:Boolean, val revision:Long, val position:Long, val payload:String)

@Entity(tableName="savings_wishes", primaryKeys=["id"], foreignKeys=[ForeignKey(entity=SavingsPlanRow::class,parentColumns=["id"],childColumns=["planId"],deferred=true),ForeignKey(entity=SavingsMovementRow::class,parentColumns=["id"],childColumns=["fulfilledMovementId"],deferred=true)], indices=[Index(value=["planId"]),Index(value=["fulfilledMovementId"],unique=true)])
data class SavingsWishRow(val id:String, val planId:String, val name:String, val amountMinor:Long, val fulfilledMovementId:String?, val revision:Long, val position:Long, val payload:String)

@Entity(tableName="budget_allocations", primaryKeys=["id"], foreignKeys=[ForeignKey(entity=BudgetRow::class,parentColumns=["ledgerId","yearMonth"],childColumns=["ledgerId","yearMonth"],deferred=true),ForeignKey(entity=CategoryRow::class,parentColumns=["id"],childColumns=["categoryId"],deferred=true)], indices=[Index(value=["ledgerId","yearMonth"]),Index(value=["categoryId"]),Index(value=["ledgerId","yearMonth","categoryId"],unique=true)])
data class BudgetAllocationRow(val id:String, val ledgerId:String, val yearMonth:String, val categoryId:String, val amountMinor:Long, val revision:Long, val position:Long, val payload:String)

@Entity(tableName="budget_reallocations", primaryKeys=["id"], foreignKeys=[ForeignKey(entity=BudgetRow::class,parentColumns=["ledgerId","yearMonth"],childColumns=["ledgerId","yearMonth"],deferred=true),ForeignKey(entity=BudgetAllocationRow::class,parentColumns=["id"],childColumns=["fromAllocationId"],deferred=true),ForeignKey(entity=BudgetAllocationRow::class,parentColumns=["id"],childColumns=["toAllocationId"],deferred=true),ForeignKey(entity=BudgetReallocationRow::class,parentColumns=["id"],childColumns=["reversalOfId"],deferred=true)], indices=[Index(value=["ledgerId","yearMonth"]),Index(value=["fromAllocationId"]),Index(value=["toAllocationId"]),Index(value=["reversalOfId"],unique=true)])
data class BudgetReallocationRow(val id:String, val ledgerId:String, val yearMonth:String, val fromAllocationId:String, val toAllocationId:String, val amountMinor:Long, val createdAt:String, val reversalOfId:String?, val position:Long, val payload:String)
